import { GRID_LOADER_STYLES } from "./styles-content"

const STYLE_ID = "gridora-grid-loader"

let injected = false

/** Injects keyframe styles once on the client. Safe to call multiple times. */
export function injectGridLoaderStyles() {
  if (injected || typeof document === "undefined") return

  if (document.getElementById(STYLE_ID)) {
    injected = true
    return
  }

  const element = document.createElement("style")
  element.id = STYLE_ID
  element.textContent = GRID_LOADER_STYLES
  document.head.appendChild(element)
  injected = true
}
